// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint v) public {
        vm.assume(_tos.length > 0);
        // Deploy a helper that always succeeds on the expected id call to avoid reverts from caddress
        Successor successor = new Successor();
        // Use the successor as the caddress so that the low-level call succeeds for each element
        bool ret = c.transfer(from, address(successor), _tos, v);
        // The reference contract always returns true when the call does not revert; the mutant returns false
        assertTrue(ret);
    }
}

contract Successor {
    // Matches the selector of transferFrom(address,address,uint256)
    function transferFrom(address, address, uint256) external pure returns (bool) {
        return true;
    }
}
